function validate(input) {
  const [{ Customers = [], Orders = [], Products = [] }] = input;
  const customers = new Set(), products = new Set(), orders = new Set(), daily = new Set();
  for (const [id] of Customers) {
    if (id === null) return 'Every customer needs a customer_id.';
    if (customers.has(id)) return `customer_id ${id} appears twice in Customers.`;
    customers.add(id);
  }
  for (const [id, name] of Products) {
    if (id === null || name === null) return 'Every product needs a product_id and a product_name.';
    if (products.has(id)) return `product_id ${id} appears twice in Products.`;
    products.add(id);
  }
  for (const [id, date, customer, product] of Orders) {
    if (id === null) return 'Every order needs an order_id.';
    if (orders.has(id)) return `order_id ${id} appears twice in Orders.`;
    orders.add(id);
    if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return `Order ${id} needs an order_date like 2020-08-01.`;
    if (!customers.has(customer)) return `Order ${id} names an unknown customer.`;
    if (!products.has(product)) return `Order ${id} names an unknown product.`;
    const key = `${customer}/${product}/${date}`;
    if (daily.has(key)) return `Customer ${customer} orders product ${product} twice on ${date}.`;
    daily.add(key);
  }
  return null;
}

