function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Winston', 'Jonathan', 'Annabelle', 'Marwan', 'Khaled', 'Mira'];
  const goods = small ? ['keyboard', 'mouse', 'screen', 'mouse', 'cable'] : ['keyboard', 'mouse', 'screen', 'hard disk', 'cable', 'webcam', 'speaker', 'charger'];
  const customerCount = small ? Math.floor(rand() * 5) : 150;
  const productCount = small ? Math.floor(rand() * 5) : 300;
  const Customers = [], Products = [], Orders = [];
  for (let id = 1; id <= customerCount; id++) Customers.push([id, pick(names)]);
  for (let id = 1; id <= productCount; id++) Products.push([id, pick(goods), 10 * (1 + Math.floor(rand() * 60))]);
  // Few dates in small sets so the latest date is often shared by several orders of one product.
  const days = small ? ['2020-07-29', '2020-07-30', '2020-08-01', '2020-08-03'] : Array.from({ length: 90 }, (_, i) => new Date(Date.UTC(2020, 5, 1 + i)).toISOString().slice(0, 10));
  const target = customerCount && productCount ? (small ? Math.floor(rand() * 9) : 2000) : 0;
  const used = new Set();
  for (let attempt = 0; Orders.length < target && attempt < target * 5; attempt++) {
    const customer = 1 + Math.floor(rand() * customerCount), product = 1 + Math.floor(rand() * productCount), date = pick(days);
    const key = `${customer}/${product}/${date}`;
    if (used.has(key)) continue;
    used.add(key);
    Orders.push([Orders.length + 1, date, customer, product]);
  }
  // Order ids follow insertion, not dates, so the newest order is rarely the largest id.
  return [{ Customers, Orders, Products }];
}
